(window.webpackJsonp=window.webpackJsonp||[]).push([[433],{757:function(t,a,e){"use strict";e.r(a);var r=e(33),s=Object(r.a)({},function(){var t=this,a=t.$createElement,e=t._self._c||a;return e("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[e("h1",{attrs:{id:"indelning-av-rostfria-stal"}},[e("a",{staticClass:"header-anchor",attrs:{href:"#indelning-av-rostfria-stal","aria-hidden":"true"}},[t._v("#")]),t._v(" Indelning av rostfria stål")]),t._v(" "),e("p",[t._v("Förutom de låglegerade stålen tillverkas flera typer höglegerade stål. Av dessa skall här de rostfria stålen behandlas. Dessa indelas i grupperna austenitiska, ferritiska, ferrit-austenitiska, martensit–austenitiska och martensitiska rostfria stål, där de austenitiska idag är de vanligaste.")]),t._v(" "),e("p",[t._v("De austenitiska stålen har höga halter av krom, Cr (ca 18 %) och nickel, Ni (ca 9 %) samt låga kolhalter. Den austenitiska strukturen gör att dessa stål är väl svets och formbara.")]),t._v(" "),e("p",[t._v("Orsaken till de rostfria stålens goda korrosionsbeständighet är att det i oxiderande miljöer bildas ett tunt oxidskikt på stålets yta. Det är krom som tillsammans med syre som bildar detta skikt. Krom är alltså det viktigaste legeringsämnet och kromhalten måste ligga över ca 12 %.")]),t._v(" "),e("p",[t._v("Trots att rostfria stål har låg kolhalt är den fullt tillräcklig för att en stor del av kolet ska utskiljas i form av kromkarbider i korngränserna vidvärmebehandling under 800 °C. Detta medför sänkt korrosionsbeständighet. Austenitiska rostfria stål levereras normalt i släckglödgat tillstånd, d.v.s. glödgade vid temperaturer mellan 1000 °C och 1100°C och därefter snabbkylning för att undvika urskiljning av korngränskarbider.")])])},[],!1,null,null,null);a.default=s.exports}}]);